      const r = round(80 * sin((2 * pi * t) / 0.5 + 0.01) + 150);
      const g = round(50 * sin((2 * pi * t) / 0.5 + 4.6) + 200);
      const b = round(100 * sin((2 * pi * t) / 0.5 + 2.3) + 150);
      const color = new Color(r, g, b);
      return color
